<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRouter} from 'vue-router';import {ArrowRight} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createRun} from '../api/runs';import LibrarySelector from '../components/LibrarySelector.vue';import Notice from '../components/common/Notice.vue';
const s=useResearchData(),auth=useAuth(),a=useAction(),router=useRouter(),selected=ref(0),chosen=ref<number[]>([]),name=ref(''),sigma=ref(.005),repeats=ref(80),seed=ref(2026),lockedWeights=ref<Record<number,number>>({}),lockBasis=ref('');
const library=computed(()=>s.libraries.find(l=>l.id===selected.value)||s.libraries[0]);
watch(()=>library.value?.id,async id=>{if(id){await s.loadLibrary(id);chosen.value=s.samples.slice(0,3).map(x=>x.id);lockedWeights.value={};lockBasis.value=''}},{immediate:true});
const lockEntries=computed(()=>s.endmembers.filter(e=>lockedWeights.value[e.id]!==undefined).map(e=>({endmember_id:e.id,code:e.code,name:e.name,weight:Number(lockedWeights.value[e.id])})));
const lockedTotal=computed(()=>lockEntries.value.reduce((n,x)=>n+(Number.isFinite(x.weight)?x.weight:0),0));
const remaining=computed(()=>1-lockedTotal.value);
const freeCount=computed(()=>Math.max(0,s.endmembers.length-lockEntries.value.length));
const anyLock=computed(()=>lockEntries.value.length>0);
const toggleLock=(id:number)=>{const next={...lockedWeights.value};if(next[id]===undefined)next[id]=0;else delete next[id];lockedWeights.value=next};
function setWeight(id:number,value:string){const next={...lockedWeights.value};next[id]=value===''?NaN:Number(value);lockedWeights.value=next}
const lockError=computed(()=>{
  if(!lockEntries.value.length)return '';
  if(lockBasis.value.trim().length<4)return '锁定配比须注明称量依据（至少4字，例如天平编号与读数）。';
  if(lockEntries.value.some(x=>!Number.isFinite(x.weight)))return '每个锁定端元都须填写配比数值。';
  if(lockEntries.value.some(x=>x.weight<0||x.weight>1))return '锁定配比必须位于0–1之间。';
  if(lockedTotal.value>1+1e-9)return '锁定配比合计超过1，剩余份额无法分摊，拒绝计算。';
  if(freeCount.value>0&&lockedTotal.value>1-1e-9)return '锁定配比合计已占满1，未锁定颜料无可分配剩余份额。';
  if(freeCount.value===0&&Math.abs(lockedTotal.value-1)>1e-9)return '全部端元锁定时锁定配比合计须为1，才能给出重建与残差。';
  return '';
});
const canSubmit=computed(()=>!a.busy.value&&chosen.value.length>=1&&chosen.value.length<=6&&chosen.value.length*repeats.value<=480&&!lockError.value&&(library.value?.supported||anyLock.value));
function submit(){a.execute(async()=>{const run=await createRun({name:name.value,library_id:library.value.id,sample_ids:chosen.value,noise_sigma:sigma.value,repeats:repeats.value,seed:seed.value,locked_weights:lockEntries.value.map(x=>({endmember_id:x.endmember_id,weight:x.weight})),lock_basis:lockBasis.value.trim()});router.push('/results?run='+run.id)})}
</script>
<template><div class="page"><div class="page-title"><div><p class="eyebrow">UNMIXING PROTOCOL / 03</p><h1>解混配置<span>非负、和为一，与固定端元假设一起生效。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><div class="editor-grid"><form @submit.prevent="submit"><label>研究名称<input aria-label="研究名称" v-model="name" minlength="2" maxlength="120" required placeholder="例如：首批矿物三样本复配研究" :disabled="auth.user?.role==='viewer'"/></label><LibrarySelector :libraries="s.libraries" :model-value="library?.id||0" @update:model-value="selected=$event"/><div v-if="library&&!library.supported" class="notice">{{library.reason}}<template v-if="anyLock">已锁定称量配比，提交后按剩余自由度重新判断可辨识性。</template></div><div class="form-heading"><span>01</span><h2>选择混合样本</h2></div><div class="sample-selector"><label v-for="sample in s.samples" :key="sample.id"><input type="checkbox" :value="sample.id" v-model="chosen"/><span>{{sample.code}}<small>{{sample.name}}</small></span></label></div><p class="caption">已选{{chosen.length}}个；允许1–6个，样本数×重复数≤480。</p><div class="form-heading"><span>02</span><h2>锁定已称量配比</h2></div><p class="caption">称量已确定的颜料按实际配比锁定；锁定值在点估计与全部条件重拟合中保持不变，其余颜料只分摊剩余份额。可辨识性按剩余自由度判断，全部锁定时仍输出重建与残差。</p><div class="lock-list"><div v-for="(e,i) in s.endmembers" :key="e.id" :class="['lock-row',lockedWeights[e.id]!==undefined?'active':'']"><label class="lock-toggle"><input type="checkbox" :checked="lockedWeights[e.id]!==undefined" :aria-label="'锁定 '+e.name" :disabled="auth.user?.role==='viewer'" @change="toggleLock(e.id)"/><span :class="['pigment','color-'+i]"/><span>{{e.name}}<small>{{e.code}}</small></span></label><label class="lock-weight"><input :aria-label="e.name+' 锁定配比'" type="number" min="0" max="1" step=".001" :value="lockedWeights[e.id]===undefined?'':lockedWeights[e.id]" :disabled="lockedWeights[e.id]===undefined||auth.user?.role==='viewer'" placeholder="0.000" @input="setWeight(e.id,($event.target as HTMLInputElement).value)"/></label></div></div><div class="lock-summary"><span>锁定合计 <b>{{Number.isFinite(lockedTotal)?lockedTotal.toFixed(3):'—'}}</b></span><span>剩余份额 <b>{{Number.isFinite(remaining)?remaining.toFixed(3):'—'}}</b></span><span>自由端元 <b>{{freeCount}}</b> 个</span></div><label v-if="anyLock">称量依据<textarea aria-label="称量依据" v-model="lockBasis" minlength="4" maxlength="600" required placeholder="记录称量设备、读数、日期或复核人；导出与研究归档会保留这段依据。"/></label><p v-if="lockError" class="lock-error" role="alert">{{lockError}}</p><div class="form-heading"><span>03</span><h2>条件测量噪声</h2></div><div class="form-row"><label>已知测量sigma<input aria-label="测量sigma" type="number" min="0" max=".2" step=".001" v-model.number="sigma"/></label><label>条件重拟合次数<input aria-label="重拟合次数" type="number" min="20" max="120" v-model.number="repeats"/></label></div><label>根随机种子<input aria-label="随机种子" type="number" min="0" max="2147483647" v-model.number="seed"/></label><p class="caption">以观测谱加独立Gaussian噪声，固定端元重拟合。锁定颜料在每次重拟合中保持称量值。范围不包括端元误差，也不保证真实配比覆盖；sigma=0时扰动退化。</p><button v-if="auth.user?.role!=='viewer'" class="primary" :disabled="!canSubmit">提交解混研究 <ArrowRight :size="16"/></button><p v-else class="role-note">阅读者可查看配置，提交研究需要研究员权限。</p></form><aside class="method-note"><span class="eyebrow">METHOD NOTE / 01</span><h2>先检查，<br/>再枚举支持集。</h2><ol><li><b>称量锁定优先</b><p>锁定配比不参与重新分配；剩余份额由自由端元分摊，噪声重拟合同样保持锁定值。</p></li><li><b>可辨识看剩余自由度</b><p>[A;1]满列秩的判断只针对自由端元。全部锁定时没有可估参数，仍按锁定值重建并给出残差。</p></li><li><b>条件范围有限</b><p>Gaussian扰动分位不是成分真值置信保证，高残差还可能来自模型失配。</p></li></ol></aside></div></div></template>
